import subprocess
import sys
import importlib.metadata as _md
from pathlib import Path

_setup_start = time.perf_counter()
def run_checked(command, cwd=None):
    print("+", " ".join(map(str, command)))
    subprocess.run(list(map(str, command)), cwd=cwd, check=True)

if not (COMFY_DIR / ".git").exists():
    run_checked(["git", "clone", "--depth", "1", "--filter=blob:none",
                 "https://github.com/Comfy-Org/ComfyUI.git", str(COMFY_DIR)])
_head = subprocess.check_output(["git", "rev-parse", "HEAD"], cwd=COMFY_DIR, text=True).strip()
if FORCE_SETUP or _head != COMFY_REF:
    run_checked(["git", "fetch", "--depth", "1", "origin", COMFY_REF], cwd=COMFY_DIR)
    run_checked(["git", "checkout", "--force", "FETCH_HEAD"], cwd=COMFY_DIR)
COMFY_COMMIT = subprocess.check_output(["git", "rev-parse", "HEAD"], cwd=COMFY_DIR, text=True).strip()
_packages = ("huggingface_hub", "transformers", "requests", "psutil", "websocket-client", "tqdm")
def installed_versions():
    try:
        return {name: _md.version(name) for name in _packages}
    except _md.PackageNotFoundError:
        return {}
_stamp_path = SESSION_ROOT / "installed_dependencies.json"
try:
    _saved = json.loads(_stamp_path.read_text())
except (OSError, ValueError):
    _saved = {}
_versions = installed_versions()
_stamp = {"commit": COMFY_COMMIT, "python": sys.version, "packages": _versions}
if FORCE_SETUP or not _versions or _saved != _stamp or _versions.get("huggingface_hub", "").split(".")[0] != "1":
    # 单次安装同时满足 ComfyUI 与文本编码器的依赖，不先升级再降级。
    run_checked([sys.executable, "-m", "pip", "install", "-q",
                 "-r", str(COMFY_DIR / "requirements.txt"),
                 "huggingface_hub>=1.5.0,<2.0", "requests>=2.31.0",
                 "psutil>=5.9.0", "websocket-client>=1.8.0", "tqdm>=4.66.0"])
    _versions = installed_versions()
    if _versions.get("huggingface_hub", "").split(".")[0] != "1":
        raise RuntimeError("huggingface_hub 必须为 1.x，以兼容文本编码器。")
    _stamp_path.write_text(json.dumps({"commit": COMFY_COMMIT, "python": sys.version,
                                    "packages": _versions}, indent=2))
else:
    print("复用本会话已安装的依赖。")
STAGE_TIMINGS["setup_seconds"] = time.perf_counter() - _setup_start
print("ComfyUI commit:", COMFY_COMMIT)

