custom_node_code = r'''
import torch
import folder_paths
import comfy.sd

class H3KaggleCLIPLoader:
    @classmethod
    def INPUT_TYPES(cls):
        devices = ["cuda:0"]
        if torch.cuda.device_count() > 1:
            devices.append("cuda:1")
        devices.append("cpu")
        return {
            "required": {
                "clip_name": (folder_paths.get_filename_list("text_encoders"),),
                "device": (devices,),
            }
        }

    RETURN_TYPES = ("CLIP",)
    FUNCTION = "load_clip"
    CATEGORY = "loaders/H3 Kaggle"

    def load_clip(self, clip_name, device):
        if device.startswith("cuda"):
            index = int(device.split(":", 1)[1])
            if index >= torch.cuda.device_count():
                raise RuntimeError(
                    f"Requested {device}, but only {torch.cuda.device_count()} CUDA device(s) are visible."
                )

        target = torch.device(device)
        model_options = {
            "load_device": target,
            "offload_device": torch.device("cpu"),
        }

        clip_path = folder_paths.get_full_path_or_raise("text_encoders", clip_name)
        clip_type = getattr(comfy.sd.CLIPType, "MINIMAX")
        clip = comfy.sd.load_clip(
            ckpt_paths=[clip_path],
            embedding_directory=folder_paths.get_folder_paths("embeddings"),
            clip_type=clip_type,
            model_options=model_options,
        )
        return (clip,)

