    "H3KaggleCLIPLoader": H3KaggleCLIPLoader,
}
NODE_DISPLAY_NAME_MAPPINGS = {
    "H3KaggleCLIPLoader": "H3 Kaggle CLIP Loader (Experimental Multi-GPU)",
}
'''

(custom_node_dir / "__init__.py").write_text(custom_node_code, encoding="utf-8")
