import hashlib
import os
import subprocess
import sys
import time
import psutil
import requests

_server_start = time.perf_counter()
SERVER_URL = f"http://127.0.0.1:{SERVER_PORT}"
PID_PATH = SESSION_ROOT / "comfyui.pid"
SERVER_STAMP_PATH = SESSION_ROOT / "comfyui_server.json"
def tail_file(path, line_count=40):
    if not path.exists():
        return "日志尚未创建。"
    return "\n".join(path.read_text(encoding="utf-8", errors="replace").splitlines()[-line_count:])
def server_ready():
    try:
        return requests.get(f"{SERVER_URL}/system_stats", timeout=3).ok
    except requests.RequestException:
        return False
env = os.environ.copy()
env["CUDA_VISIBLE_DEVICES"] = ",".join(str(i) for i in range(torch.cuda.device_count()))
env["HF_HOME"] = str(SESSION_ROOT / "hf_home")
command = [sys.executable, "main.py", "--listen", "127.0.0.1", "--port", str(SERVER_PORT),
           "--lowvram", "--preview-method", "none", "--disable-metadata",
           "--output-directory", str(COMFY_OUTPUT_DIR), "--temp-directory", str(COMFY_TEMP_DIR),
           "--reserve-vram", "0.8"]
fingerprint = hashlib.sha256(json.dumps({
    "command": command, "commit": COMFY_COMMIT, "python": sys.version,
    "custom_node": custom_node_code, "packages": installed_versions(),
    "devices": env["CUDA_VISIBLE_DEVICES"],
}, sort_keys=True).encode()).hexdigest()
try:
    old = json.loads(SERVER_STAMP_PATH.read_text())
except (OSError, ValueError):
    old = {}
owned = None
try:
    pid = int(old.get("pid") or PID_PATH.read_text().strip())
    process = psutil.Process(pid)
    if (process.cwd() == str(COMFY_DIR) and "main.py" in process.cmdline()
            and ("created" not in old or abs(process.create_time() - old["created"]) < 1)):
        owned = process
except (OSError, ValueError, psutil.Error):
    pass
SERVER_REUSED = bool(REUSE_SERVER and owned and old.get("fingerprint") == fingerprint and server_ready())
if SERVER_REUSED:
    print("复用 ComfyUI 服务和节点缓存；无需重启或重新加载全部模型。")
else:
    if owned:
        owned.terminate()
        try:
            owned.wait(timeout=15)
        except psutil.TimeoutExpired:
            owned.kill()
            owned.wait(timeout=5)
    elif server_ready():
        raise RuntimeError("端口已被其他服务占用，请更换 SERVER_PORT。")
    print("+", " ".join(command))
    with LOG_PATH.open("w", encoding="utf-8") as log_handle:
        SERVER_PROCESS = subprocess.Popen(command, cwd=COMFY_DIR, env=env,
                                          stdout=log_handle, stderr=subprocess.STDOUT)
    PID_PATH.write_text(str(SERVER_PROCESS.pid))
    deadline = time.monotonic() + 240
    while time.monotonic() < deadline:
        if SERVER_PROCESS.poll() is not None:
            raise RuntimeError("ComfyUI 启动失败：\n" + tail_file(LOG_PATH, 100))
        if server_ready():
            break
        time.sleep(2)
    else:
        raise RuntimeError("ComfyUI 启动超时：\n" + tail_file(LOG_PATH, 100))
    SERVER_STAMP_PATH.write_text(json.dumps({"pid": SERVER_PROCESS.pid,
        "created": psutil.Process(SERVER_PROCESS.pid).create_time(), "fingerprint": fingerprint}))
    print("ComfyUI 服务已就绪。")
STAGE_TIMINGS["server_seconds"] = time.perf_counter() - _server_start

import json
from pathlib import Path

DIFFUSION_NAME = "minimax_h3_fl2va_pruned_int8_convrot.safetensors"
TEXT_ENCODER_NAME = "qwen3vl_32b_minimax_h3_nvfp4_awq.safetensors"
VIDEO_VAE_NAME = "minimax_h3_video_vae_fp16.safetensors"
AUDIO_VAE_NAME = "minimax_h3_audio_vae_fp32.safetensors"

def snap_h3_frames(seconds: float) -> int:
    requested = max(5, int(float(seconds) * 24 + 0.5))
    return requested + (5 - (requested % 17)) % 17

def build_h3_workflow(
    *,
    prompt: str,
    width: int,
    height: int,
    duration_seconds: float,
    steps: int,
    seed: int,
    use_gpu1_clip: bool,
    filename_prefix: str,
):
    if width % 32 or height % 32:
        raise ValueError("H3 width and height must be divisible by 32.")

    length = snap_h3_frames(duration_seconds)
    use_custom_clip = (
        use_gpu1_clip
        and torch.cuda.device_count() > 1
        and MULTIGPU_NODE_AVAILABLE
    )

    if use_custom_clip:
        clip_node = {
            "class_type": "H3KaggleCLIPLoader",
            "inputs": {
                "clip_name": TEXT_ENCODER_NAME,
                "device": "cuda:1",
            },
        }
    else:
        clip_node = {
            "class_type": "CLIPLoader",
            "inputs": {
                "clip_name": TEXT_ENCODER_NAME,
                "type": "minimax",
                "device": "default",
            },
        }

    workflow = {
        "6": {
            "class_type": "UNETLoader",
            "inputs": {
                "unet_name": DIFFUSION_NAME,
                "weight_dtype": "default",
            },
        },
        "11": {
            "class_type": "VAELoader",
            "inputs": {"vae_name": VIDEO_VAE_NAME},
        },
        "13": clip_node,
        "15": {
            "class_type": "RandomNoise",
            "inputs": {"noise_seed": int(seed)},
        },
        "17": {
            "class_type": "KSamplerSelect",
            "inputs": {"sampler_name": "res_multistep"},
        },
        "104": {
            "class_type": "MiniMaxH3ImageToVideo",
            "inputs": {
                "clip": ["13", 0],
                "vae": ["11", 0],
                "prompt": prompt,
                "width": int(width),
                "height": int(height),
                "length": int(length),
            },
        },
        "16": {
            "class_type": "BasicGuider",
            "inputs": {
                "model": ["6", 0],
                "conditioning": ["104", 0],
            },
        },
        "9": {
            "class_type": "BasicScheduler",
            "inputs": {
                "model": ["6", 0],
                "scheduler": "simple",
                "steps": int(steps),
                "denoise": 1.0,
            },
        },
        "14": {
            "class_type": "SamplerCustomAdvanced",
            "inputs": {
                "noise": ["15", 0],
                "guider": ["16", 0],
                "sampler": ["17", 0],
                "sigmas": ["9", 0],
                "latent_image": ["104", 1],
            },
        },
        "10": {
            "class_type": "VAEDecode",
            "inputs": {
                "samples": ["14", 0],
                "vae": ["11", 0],
            },
        },
        "24": {
            "class_type": "VAELoader",
            "inputs": {"vae_name": AUDIO_VAE_NAME},
        },
        "23": {
            "class_type": "VAEDecodeAudio",
            "inputs": {
                "samples": ["14", 0],
                "vae": ["24", 0],
            },
        },
        "91": {
            "class_type": "CreateVideo",
            "inputs": {
                "images": ["10", 0],
                "audio": ["23", 0],
                "fps": 24.0,
                "bit_depth": 8,
            },
        },
        "92": {
            "class_type": "SaveVideo",
            "inputs": {
                "video": ["91", 0],
                "filename_prefix": filename_prefix,
                "format": "auto",
                "codec": "auto",
            },
        },
    }

    if USE_TURBO:
        workflow["119"] = {"class_type": "LoraLoaderModelOnly", "inputs": {
            "model": ["6", 0], "lora_name": TURBO_LORA_NAME, "strength_model": 1.0}}
        workflow["120"] = {"class_type": "MiniMaxH3SigmaShift", "inputs": {
            "model": ["119", 0], "shift_video": TURBO_SHIFT_VIDEO, "shift_audio": TURBO_SHIFT_AUDIO}}
        workflow["16"]["inputs"]["model"] = ["120", 0]
        workflow["9"]["inputs"]["model"] = ["120", 0]
        workflow["17"]["inputs"]["sampler_name"] = SAMPLER_NAME

    return workflow, {
        "generation_mode": GENERATION_MODE,
        "turbo_lora": TURBO_LORA_NAME if USE_TURBO else None,
        "sampler": SAMPLER_NAME,
        "width": width,
        "height": height,
        "duration_requested": duration_seconds,
        "frames": length,
        "actual_duration": length / 24,
        "steps": steps,
        "seed": seed,
        "dual_gpu_clip": use_custom_clip,
    }

preview_workflow, preview_config = build_h3_workflow(
    prompt=PROMPT,
    width=WIDTH,
    height=HEIGHT,
    duration_seconds=DURATION_SECONDS,
    steps=STEPS,
    seed=SEED,
    use_gpu1_clip=USE_SECOND_T4_FOR_TEXT_ENCODER,
    filename_prefix=SAVE_PREFIX,
)

workflow_path = FINAL_OUTPUT_DIR / "minimax_h3_api_workflow.json"
workflow_path.write_text(json.dumps(preview_workflow, indent=2), encoding="utf-8")

print(json.dumps(preview_config, indent=2))
print("Saved API workflow:", workflow_path)

import json
import shutil
import time
import uuid
from pathlib import Path

import requests
import websocket
from IPython.display import HTML, display
from tqdm.auto import tqdm

VIDEO_EXTENSIONS = {".mp4", ".webm", ".mkv", ".mov"}

NODE_STAGES = {
    "119": "加载 Turbo LoRA",
    "120": "设置音视频采样时间表",
    "6": "加载 H3 扩散模型",
    "11": "加载视频 VAE",
    "13": "加载文本编码器",
    "15": "准备噪声",
    "17": "准备采样器",
    "104": "编码提示词并准备音视频潜变量",
    "16": "准备条件",
    "9": "准备采样时间表",
    "14": "采样视频与立体声音频",
    "24": "加载音频 VAE",
    "23": "解码音频",
    "10": "解码视频",
    "91": "合成音视频",
    "92": "保存视频",
}

def collect_videos():
    return {
        p.resolve()
        for p in COMFY_OUTPUT_DIR.rglob("*")
        if p.is_file() and p.suffix.lower() in VIDEO_EXTENSIONS
    }

def free_comfy_memory():
    try:
        requests.post(
            f"{SERVER_URL}/free",
            json={"unload_models": True, "free_memory": True},
            timeout=30,
        )
    except Exception:
        pass
    if torch.cuda.is_available():
        torch.cuda.empty_cache()

def queue_workflow(workflow, client_id):
    response = requests.post(
        f"{SERVER_URL}/prompt",
        json={"prompt": workflow, "client_id": client_id},
        timeout=120,
    )
    if not response.ok:
        raise RuntimeError(
            f"ComfyUI rejected the workflow (HTTP {response.status_code}):\n"
            f"{response.text}\n\nLog tail:\n{tail_file(LOG_PATH, 100)}"
        )
    data = response.json()
    if "prompt_id" not in data:
        raise RuntimeError(f"Unexpected /prompt response: {data}")
    return data["prompt_id"]

def read_prompt_history(prompt_id):
    response = requests.get(f"{SERVER_URL}/history/{prompt_id}", timeout=30)
    response.raise_for_status()
    return response.json().get(prompt_id)

def status_card(title, detail="", state="running"):
    palette = {
        "running": ("#70d85c", "rgba(70,150,60,.10)"),
        "success": ("#54d97b", "rgba(50,160,90,.12)"),
        "error": ("#ef6a6a", "rgba(180,50,50,.10)"),
        "waiting": ("#d5b85c", "rgba(160,130,40,.10)"),
    }
    accent, background = palette[state]
    return HTML(f"""
    <div style="
        border:1px solid {accent};
        border-left:7px solid {accent};
        border-radius:8px;
        padding:12px 15px;
        margin:8px 0 10px 0;
        background:{background};
        font-family:system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;
    ">
      <div style="font-size:16px;font-weight:750;">{title}</div>
      <div style="margin-top:4px;opacity:.76;">{detail}</div>
    </div>
    """)

def wait_for_prompt(prompt_id, expected_steps, ws=None):
    started = time.time()
    current_node = None
    last_stage = "等待 ComfyUI"
    status_handle = display(
        status_card(last_stage, "首次加载模型需要一些时间。", "waiting"),
        display_id=True,
    )

    progress_bar = tqdm(
        total=int(expected_steps),
        desc="H3 采样",
        unit="step",
        dynamic_ncols=True,
        leave=True,
        mininterval=0.2,
        bar_format="{desc}: {percentage:3.0f}%|{bar}| {n_fmt}/{total_fmt} "
                   "[{elapsed}<{remaining}, {rate_fmt}]",
    )

    def update_stage(stage, state="running"):
        nonlocal last_stage
        last_stage = stage
        elapsed = time.time() - started
        print("@@H3_PROGRESS@@" + json.dumps({"stage": stage, "state": state,
              "step": int(progress_bar.n), "steps": int(progress_bar.total),
              "elapsed": round(elapsed, 1)}), flush=True)
        status_handle.update(
            status_card(stage, f"已用时间： {elapsed / 60:.1f} 分钟", state)
        )

    try:
        while True:
            message = None

            if ws is not None:
                try:
                    raw = ws.recv()
                    if isinstance(raw, str):
                        message = json.loads(raw)
                    # Binary messages are latent previews; this notebook does not
                    # display them because H3 previews add memory and UI overhead.
                except websocket.WebSocketTimeoutException:
                    message = None
                except Exception:
                    ws = None
                    update_stage(
                        "实时进度连接中断，改用运行历史查询",
                        "waiting",
                    )

            if message is not None:
                message_type = message.get("type")
                data = message.get("data", {})

                message_prompt_id = data.get("prompt_id")
                if message_prompt_id is not None and message_prompt_id != prompt_id:
                    continue

                if message_type == "executing":
                    node = data.get("node")
                    if node is None:
                        break
                    current_node = str(node)
                    update_stage(NODE_STAGES.get(current_node, "运行 H3 工作流"))

                elif message_type == "progress":
                    progress_node = str(data.get("node", current_node))
                    if progress_node == "14":
                        maximum = int(data.get("max", expected_steps))
                        value = int(data.get("value", 0))
                        if maximum > 0 and progress_bar.total != maximum:
                            progress_bar.total = maximum
                        value = min(value, progress_bar.total)
                        if value > progress_bar.n:
                            progress_bar.update(value - progress_bar.n)
                        update_stage("采样视频与立体声音频")

                elif message_type in ("execution_error", "execution_interrupted"):
                    raise RuntimeError(
                        "ComfyUI execution failed:\n"
                        + json.dumps(data, indent=2, default=str)[-12000:]
                        + "\n\nLog tail:\n"
                        + tail_file(LOG_PATH, 120)
                    )

                elif message_type == "execution_success":
                    break

            # HTTP history is both a completion check and a fallback when WebSocket
            # messages are unavailable.
            history = read_prompt_history(prompt_id)
            if history is not None:
                status = history.get("status", {})
                if status.get("status_str") == "error":
                    raise RuntimeError(
                        "ComfyUI execution failed:\n"
                        + json.dumps(status.get("messages", []), indent=2, default=str)[-12000:]
                        + "\n\nLog tail:\n"
                        + tail_file(LOG_PATH, 120)
                    )
                if status.get("completed", False):
                    if progress_bar.n < progress_bar.total:
                        progress_bar.update(progress_bar.total - progress_bar.n)
                    update_stage("生成完成", "success")
                    return history

            # Avoid a busy loop if the WebSocket is unavailable.
            if ws is None:
                time.sleep(3)

        # The completion WebSocket event can arrive just before history is stored.
        for _ in range(20):
            history = read_prompt_history(prompt_id)
            if history is not None:
                status = history.get("status", {})
                if status.get("status_str") == "error":
                    raise RuntimeError(
                        "ComfyUI execution failed:\n"
                        + json.dumps(status.get("messages", []), indent=2, default=str)[-12000:]
                        + "\n\nLog tail:\n"
                        + tail_file(LOG_PATH, 120)
                    )
                if status.get("completed", False):
                    if progress_bar.n < progress_bar.total:
                        progress_bar.update(progress_bar.total - progress_bar.n)
                    update_stage("生成完成", "success")
                    return history
            time.sleep(0.5)

        raise RuntimeError(
            "ComfyUI announced completion, but the finished history record was not found."
        )

    except Exception:
        status_handle.update(
            status_card(
                "生成因错误停止",
                "Open the optional diagnostics section or inspect minimax_h3_comfyui.log.",
                "error",
            )
        )
        raise
    finally:
        progress_bar.close()

def execute_attempt(attempt):
    attempt_started = time.perf_counter()
    label = attempt["label"]
    prefix = f"{SAVE_PREFIX}_{label.replace(' ', '_').replace('/', '_')}"
    workflow, resolved = build_h3_workflow(
        prompt=PROMPT,
        width=attempt["width"],
        height=attempt["height"],
        duration_seconds=attempt["duration"],
        steps=attempt["steps"],
        seed=SEED,
        use_gpu1_clip=attempt["gpu1_clip"],
        filename_prefix=prefix,
    )

    display(HTML(f"""
    <div style="
        border:1px solid #78a96a;
        border-radius:8px;
        padding:11px 15px;
        margin:8px 0;
        background:rgba(70,120,60,.07);
    ">
      <b>本次尝试：</b> {label.replace('_', ' ')} &nbsp;·&nbsp;
      <b>{resolved['width']}×{resolved['height']}</b> &nbsp;·&nbsp;
      <b>{resolved['actual_duration']:.2f}s</b> &nbsp;·&nbsp;
      <b>{resolved['steps']} steps</b> &nbsp;·&nbsp;
      双 T4 文本编码： <b>{'yes' if resolved['dual_gpu_clip'] else 'no'}</b>
    </div>
    """))

    before = collect_videos()
    client_id = str(uuid.uuid4())
    ws = None

    try:
        ws = websocket.WebSocket()
        ws.settimeout(5)
        ws.connect(
            f"ws://127.0.0.1:{SERVER_PORT}/ws?clientId={client_id}",
            timeout=30,
        )
    except Exception:
        ws = None

    try:
        prompt_id = queue_workflow(workflow, client_id)
        history = wait_for_prompt(
            prompt_id,
            expected_steps=attempt["steps"],
            ws=ws,
        )
    finally:
        if ws is not None:
            try:
                ws.close()
            except Exception:
                pass

    video_records = history.get("outputs", {}).get("92", {}).get("images", [])
    candidates = []
    output_root = COMFY_OUTPUT_DIR.resolve()
    for record in video_records:
        if record.get("type") != "output":
            continue
        candidate = (output_root / record.get("subfolder", "") / record.get("filename", "")).resolve()
        if candidate.is_relative_to(output_root) and candidate.is_file() and candidate.suffix.lower() in VIDEO_EXTENSIONS:
            candidates.append(candidate)
    # 部分 SaveVideo 版本使用视频专用字段，文件系统兜底也只接受本次新增文件。
    if not candidates:
        candidates = sorted(collect_videos() - before, key=lambda p: p.stat().st_mtime)
    if not candidates:
        raise RuntimeError("本次生成没有对应视频，拒绝复用旧视频。\n" + tail_file(LOG_PATH, 100))
    new_videos = candidates
    resolved["generation_seconds"] = time.perf_counter() - attempt_started
    return new_videos[-1], resolved, prompt_id, history

requested_dual = bool(
    USE_SECOND_T4_FOR_TEXT_ENCODER
    and torch.cuda.device_count() > 1
    and MULTIGPU_NODE_AVAILABLE
)

attempts = [
    {
        "label": "requested_dual_t4" if requested_dual else "requested_official",
        "width": WIDTH,
        "height": HEIGHT,
        "duration": DURATION_SECONDS,
        "steps": STEPS,
        "gpu1_clip": requested_dual,
    }
]

if AUTO_FALLBACK:
    attempts.extend([
        {
            "label": "low_vram_dual_t4",
            "width": 512,
            "height": 288,
            "duration": 4.0,
            "steps": STEPS if USE_TURBO else min(STEPS, 16),
            "gpu1_clip": requested_dual,
        },
        {
            "label": "low_vram_official_single_device",
            "width": 512,
            "height": 288,
            "duration": 4.0,
            "steps": STEPS if USE_TURBO else min(STEPS, 12),
            "gpu1_clip": False,
        },
    ])

# Remove exact duplicate attempts while preserving order.
unique_attempts = []
seen = set()
for item in attempts:
    key = (
        item["width"], item["height"], item["duration"],
        item["steps"], item["gpu1_clip"],
    )
    if key not in seen:
        seen.add(key)
        unique_attempts.append(item)

def is_memory_failure(error_text: str) -> bool:
    text = error_text.lower()
    memory_markers = (
        "out of memory",
        "cuda error: memory",
        "cuda out of memory",
        "allocation failed",
        "not enough memory",
        "cublas_status_alloc_failed",
    )
    return any(marker in text for marker in memory_markers)

errors = []
SUCCESS = None

for attempt_index, attempt in enumerate(unique_attempts):
    try:
        SUCCESS = execute_attempt(attempt)
        break
    except Exception as exc:
        error_text = f"{type(exc).__name__}: {exc}"
        errors.append({"attempt": attempt, "error": error_text})

        has_more_attempts = attempt_index + 1 < len(unique_attempts)
        if not (AUTO_FALLBACK and has_more_attempts and is_memory_failure(error_text)):
            break

        display(status_card(
            "显存不足，切换到较小生成参数",
            "卸载失败的模型状态后重试。",
            "waiting",
        ))
        free_comfy_memory()
        time.sleep(5)

if SUCCESS is None:
    error_path = FINAL_OUTPUT_DIR / "minimax_h3_attempt_errors.json"
    error_path.write_text(json.dumps(errors, indent=2), encoding="utf-8")
    raise RuntimeError(
        "All H3 attempts failed. Inspect these files:\n"
        f"- {LOG_PATH}\n"
        f"- {error_path}\n\n"
        + (errors[-1]["error"] if errors else "No error details were captured.")
    )

generated_path, RESOLVED_CONFIG, PROMPT_ID, HISTORY = SUCCESS
final_suffix = generated_path.suffix.lower() or ".mp4"
FINAL_VIDEO = FINAL_OUTPUT_DIR / f"minimax_h3_final{final_suffix}"
shutil.copy2(generated_path, FINAL_VIDEO)

